import peaks from "./preview-peaks.json";

/**
 * Audio previews shown in the product section.
 *
 * Everything here comes from the bundle itself: one-shots are kit samples,
 * and MIDI previews are bundle MIDI patterns played with those same samples.
 * The MP3s in /public/previews and the waveform `peaks` (normalized 0–1
 * amplitude buckets) are generated by scripts/render-previews.py.
 */
export type Preview = {
  id: keyof typeof peaks;
  label: string;
  /** Short context line, e.g. tempo. */
  detail?: string;
};

export const MIDI_PREVIEWS: Preview[] = [
  // Single parts are playable in the MIDI kits section; this is the only
  // place every part is heard layered together.
  { id: "midi-groove", label: "Psycho Kit - Full Groove", detail: "133 BPM" },
];

export const ONE_SHOT_PREVIEWS: Preview[] = [
  { id: "open-hat", label: "Black Mirror - Open Hihat" },
  { id: "snare", label: "Toronto - Snare" },
  { id: "hihat", label: "Heist - Hihat" },
  { id: "kick", label: "Vice City - Kick" },
];

export const previewSrc = (id: Preview["id"]) => `/previews/${id}.mp3`;
export const previewPeaks = (id: Preview["id"]): number[] => peaks[id];
